r:1px solid #ccd6e7;border-radius:4px}@media(max-width:800px){.admin{padding-inline:14px}.topbar{padding:0 14px;gap:5px}.brand{display:none}nav{overflow:auto}.metrics{grid-template-columns:repeat(2,1fr)}.row{grid-template-columns:1fr}.title{align-items:flex-start;flex-direction:column}.back{margin-left:auto}}
.operation-grid{display:grid;gap:16px;margin-top:22px}.operation-grid section{border-top:1px solid #e5ebf4;padding-top:15px}.operation-grid h3{margin:0 0 8px;font-size:15px}.operation-row{display:grid;grid-template-columns:80px 1fr 90px auto;gap:10px;align-items:center;margin:0;padding:9px 0;border-top:1px solid #edf0f5;font-size:12px}.operation-row em{color:#71809a;font-style:normal}.operation-row a{color:#2858b8;font-weight:700}</style>
